-- Creator Signal OS: PostgreSQL + pgvector foundation
create extension if not exists pgcrypto;
create extension if not exists vector;
create type public.source_kind as enum ('instagram_export','rss','saved_links','comments','manual');
create type public.ingestion_status as enum ('queued','running','succeeded','failed');
create type public.feedback_kind as enum ('save','dismiss','like','dislike','rating','note');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, created_at timestamptz not null default now());
create table public.sources (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, kind public.source_kind not null, name text not null, config jsonb not null default '{}', active boolean not null default true, created_at timestamptz not null default now());
create table public.ingestion_runs (id uuid primary key default gen_random_uuid(), source_id uuid not null references public.sources(id) on delete cascade, status public.ingestion_status not null default 'queued', idempotency_key text not null unique, started_at timestamptz, completed_at timestamptz, error text, created_at timestamptz not null default now());
create table public.source_items (id uuid primary key default gen_random_uuid(), source_id uuid not null references public.sources(id) on delete cascade, external_id text not null, canonical_url text, title text, body text, author text, published_at timestamptz, metadata jsonb not null default '{}', provenance jsonb not null default '{}', content_hash text not null, created_at timestamptz not null default now(), unique(source_id,external_id));
create table public.taste_nodes (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, node_type text not null check(node_type in ('concept','theme','creator','product','style','place','format')), label text not null, description text, embedding vector(1536), confidence real not null default 0 check(confidence between 0 and 1), pinned boolean not null default false, muted boolean not null default false, metadata jsonb not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.embeddings (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, source_item_id uuid references public.source_items(id) on delete cascade, taste_node_id uuid references public.taste_nodes(id) on delete cascade, model text not null, dimensions int not null, vector vector(1536) not null, content_hash text not null, created_at timestamptz not null default now(), check ((source_item_id is not null) or (taste_node_id is not null)));
create table public.signal_edges (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, from_node_id uuid not null references public.taste_nodes(id) on delete cascade, to_node_id uuid not null references public.taste_nodes(id) on delete cascade, relation text not null, weight real not null default 0, evidence jsonb not null default '{}', created_at timestamptz not null default now(), unique(user_id,from_node_id,to_node_id,relation));
create table public.feedback (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, source_item_id uuid references public.source_items(id) on delete cascade, taste_node_id uuid references public.taste_nodes(id) on delete cascade, recommendation_id uuid, kind public.feedback_kind not null, value jsonb not null default '{}', created_at timestamptz not null default now());
create table public.briefings (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, cadence text not null check(cadence in ('daily','weekly')), period_start date not null, period_end date not null, content jsonb not null, model text, score_snapshot jsonb not null default '{}', created_at timestamptz not null default now(), unique(user_id,cadence,period_start));
create index taste_nodes_embedding_idx on public.taste_nodes using hnsw (embedding vector_cosine_ops);
create index embeddings_vector_idx on public.embeddings using hnsw (vector vector_cosine_ops);
create index source_items_source_time_idx on public.source_items(source_id,published_at desc);
create or replace function public.is_owner(target uuid) returns boolean language sql stable security definer set search_path=public as $$ select auth.uid()=target $$;
alter table public.profiles enable row level security; alter table public.sources enable row level security; alter table public.ingestion_runs enable row level security; alter table public.source_items enable row level security; alter table public.taste_nodes enable row level security; alter table public.embeddings enable row level security; alter table public.signal_edges enable row level security; alter table public.feedback enable row level security; alter table public.briefings enable row level security;
create policy profiles_self on public.profiles for all using (public.is_owner(id)) with check (public.is_owner(id));
create policy sources_self on public.sources for all using (public.is_owner(user_id)) with check (public.is_owner(user_id));
create policy runs_self on public.ingestion_runs for all using (exists(select 1 from sources s where s.id=source_id and public.is_owner(s.user_id))) with check (exists(select 1 from sources s where s.id=source_id and public.is_owner(s.user_id)));
create policy items_self on public.source_items for all using (exists(select 1 from sources s where s.id=source_id and public.is_owner(s.user_id))) with check (exists(select 1 from sources s where s.id=source_id and public.is_owner(s.user_id)));
create policy nodes_self on public.taste_nodes for all using (public.is_owner(user_id)) with check (public.is_owner(user_id));
create policy embeddings_self on public.embeddings for all using (public.is_owner(user_id)) with check (public.is_owner(user_id));
create policy edges_self on public.signal_edges for all using (public.is_owner(user_id)) with check (public.is_owner(user_id));
create policy feedback_self on public.feedback for all using (public.is_owner(user_id)) with check (public.is_owner(user_id));
create policy briefings_self on public.briefings for all using (public.is_owner(user_id)) with check (public.is_owner(user_id));